T(draw,'(a) Astronaut frame — shuttle',150,22,16,'#333','middle','bold');
T(draw,'(b) Earth frame — shuttle moves',560,22,16,'#333','middle','bold');
T(draw,'(c) The geometry',560,340,16,'#333','middle','bold');

/* ---------- dynamic groups ---------- */
var gA=draw.group(), gB=draw.group(), gC=draw.group();

function drawA(){
