function drawB(){
  gB.clear();
  var b=gB.group();
  if(frame!=='earth') b.opacity(0.35);
  var gam=1/Math.sqrt(1-v*v);
  var Lpx=(v/0.9)*130;               // pixel half-base
  var x0=360;                        // first snapshot left edge
  var sw=110, sh=130, sy=60;
  var snaps=[x0, x0+Lpx, x0+2*Lpx];
  var labels=['Beginning event','','Ending event'];
  for(var i=0;i<3;i++){
    var sx=snaps[i];
    b.rect(sw,sh).move(sx,sy).radius(10).fill('#f4f4f6').stroke({color:'#777',width:1.5}).attr({'stroke-dasharray':'6,4'});
    b.rect(34,7).move(sx+sw/2-17,sy+8).fill('#9db8c4').stroke({color:'#556',width:1});
    b.rect(22,13).move(sx+sw/2-11,sy+sh-20).fill('#ccc').stroke({color:'#666',width:1});
    burst(b,sx+sw/2-20,sy+sh-13);
    clock(b,sx+sw-18,sy+sh-16,12,0.3,'','#222');
    if(labels[i]) T(b,labels[i],sx+sw/2,sy+sh+58,11);
  }
  // purple zigzag
  var p1=[snaps[0]+sw/2-20,sy+sh-13];
  var pm=[snaps[1]+sw/2,sy+12];
  var p2=[snaps[2]+sw/2,sy+sh-13];
  b.line(p1[0],p1[1],pm[0],pm[1]).stroke({color:PURPLE,width:2.5});
  b.line(pm[0],pm[1],p2[0],p2[1]).stroke({color:PURPLE,width:2.5});
  arrowHead(b,(p1[0]+pm[0])/2,(p1[1]+pm[1])/2,Math.atan2(pm[1]-p1[1],pm[0]-p1[0]),PURPLE);
  arrowHead(b,(p2[0]+pm[0])/2,(p2[1]+pm[1])/2,Math.atan2(p2[1]-pm[1],p2[0]-pm[0]),PURPLE);
  T(b,'s',(p1[0]+pm[0])/2-12,(p1[1]+pm[1])/2-8,13,PURPLE);
  T(b,'s',(p2[0]+pm[0])/2+12,(p2[1]+pm[1])/2-8,13,PURPLE);
  // brackets below
  var by=sy+sh+28;
  b.line(snaps[0]+sw/2,by,snaps[1]+sw/2,by).stroke({color:'#444',width:1.5});
  b.line(snaps[1]+sw/2,by,snaps[2]+sw/2,by).stroke({color:'#444',width:1.5);
  [[snaps[0]+sw/2,by],[snaps[1]+sw/2,by],[snaps[2]+sw/2,by]].forEach(function(q){
    b.line(q[0],q[1]-4,q[0],q[1]+4).stroke({color:'#444',width:1.5});});
  T(b,'L = vΔt/2',(snaps[0]+snaps[1])/2+sw/2,by+6,12);
  T(b,'L',(snaps[1]+snaps[2])/2+sw/2,by+6,12);
  // D bracket on last snapshot
  var lx=snaps[2]+sw+10;
  b.line(lx,sy+12,lx,sy+sh-13).stroke({color:'#444',width:1.5});
  b.line(lx-4,sy+12,lx+4,sy+12).stroke({color:'#444',width:1.5});
  b.line(lx-4,sy+sh-13,lx+4,sy+sh-13).stroke({color:'#444',width:1.5});
  T(b,'D',lx+12,sy+sh/2-7,14);
  // ground + observer
  b.polygon('300,300 860,300 890,318 270,318').fill(TAN).stroke({color:'#c5bda8',width:1});
  var ox=560;
  b.circle(11).center(ox,236).fill('#e0b48c');
  b.rect(20,34).move(ox-10,246).radius(7).fill('#8aa65b');
  b.rect(8,22).move(ox-9,278).radius(3).fill('#5b6b8a');
  b.rect(8,22).move(ox+1,278).radius(3).fill('#5b6b8a');
  T(b,'Observer on Earth',ox-80,286,12);
  clock(b,ox+60,258,20,0.55,'Δt = '+gam.toFixed(2)+'Δτ',PURPLE);
  // event highlight
  if(evIdx===1) b.circle(15).center(p1[0],p1[1]).fill('none').stroke({color:'#e33',width:3});
  if(evIdx===2) b.circle(15).center(pm[0],pm[1]).fill('none').stroke({color:'#e33',width:3});
  if(evIdx===3) b.circle(15).center(p2[0],p2[1]).fill('none').stroke({color:'#e33',width:3});
  if(evIdx>0) T(b,'Path: 2s = 2√(D²+L²)',560,42,13,PURPLE,'middle','bold');
  // comparison readout
  T(b,'Δτ = 1.00  vs  Δt = '+gam.toFixed(2)+'  (γ = '+gam.toFixed(2)+')',560,330,13,gam>1.01?PURPLE:'#333','middle','bold');
}

function drawC(){
  gC.clear();
  var c=gC.group();
  var Lpx=(v/0.9)*170;
  var cx=560, baseY=590, apexY=410;
  var bl=[cx-Lpx,baseY], br=[cx+Lpx,baseY], ap=[cx,apexY];
  c.line(bl[0],bl[1],ap[0],ap[1]).stroke({color:PURPLE,width:2.5});
  c.line(ap[0],ap[1],br[0],br[1]).stroke({color:PURPLE,width:2.5});
  c.line(bl[0],bl[1],br[0],br[1]).stroke({color:'#333',width:2});
  c.line(ap[0],ap[1],cx,baseY).stroke({color:'#333',width:2});
  arrowHead(c,(bl[0]+ap[0])/2,(bl[1]+ap[1])/2,Math.atan2(ap[1]-bl[1],ap[0]-bl[0]),PURPLE);
  arrowHead(c,(br[0]+ap[0])/2,(br[1]+ap[1])/2,Math.atan2(br[1]-ap[1],br[0]-ap[0]),PURPLE);
  T(c,'s',(bl[0]+ap[0])/2-14,(bl[1]+ap[1])/2,14,PURPLE);
  T(c,'s',(br[0]+ap[0])/2+14,(br[1]+ap[1])/2,14,PURPLE);
  T(c,'D',cx+14,(apexY+baseY)/2,14);
  T(c,'L = vΔt/2',cx-Lpx/2,baseY+8,13);
  T(c,'L',cx+Lpx/2,baseY+8,13);
  T(c,'s = √( D² + L² )',cx,372,16,'#333','middle','bold');
  // event vertex highlight
  var pts=[null,bl,ap,br];
  if(evIdx>0) c.circle(12).center(pts[evIdx][0],pts[evIdx][1]).fill('none').stroke({color:'#e33',width:3});
}

function redrawAll(){ drawA(); drawB(); drawC(); }

/* ---------- interactions ---------- */
function update_shuttleSpeed(val){ v=val; redrawAll(); }
function toggle_observerFrame(f){
  frame=f;
  document.getElementById('frameAstroBtn').className = f==='astro'?'active':'';
  document.getElementById('frameEarthBtn').className = f==='earth'?'active':'';
  redrawAll();
}
function trigger_eventStep(){
  evIdx=(evIdx+1)%EVSTATES.length;
  document.getElementById('eventLabel').textContent='Pulse: '+EVSTATES[evIdx];
  redrawAll();
}
function setEvent(state){
  evIdx=EVSTATES.indexOf(state); if(evIdx<0) evIdx=0;
  document.getElementById('eventLabel').textContent='Pulse: '+EVSTATES[evIdx];
  redrawAll();
}

/* ---------- demo steps ---------- */
var demoSteps=[
 {title:"The astronaut's clock",
  narration:"In the shuttle frame the pulse travels straight up to the mirror and back, covering exactly 2D, and the astronaut's clock reads Δτ. The apparatus does not move relative to her.",
  state:{observerFrame:'astro',eventStep:'idle'}},
 {title:"Same events, seen from Earth",
  narration:"Switch to the Earth frame: between emission and reception the cabin has moved, so the same pulse must chase the mirror along two diagonals totaling 2s > 2D. Because light's speed is the same for both observers, the longer path means a longer measured time Δt.",
  state:{observerFrame:'earth',eventStep:'idle'}},
 {title:"Speed sets the dilation",
  narration:"Drag the speed slider: faster shuttle motion spreads the snapshots apart, grows L and s, and the Earth clock Δt pulls further ahead of Δτ. At v = 0 the diagonal collapses to the vertical and the clocks agree.",
  state:{observerFrame:'earth',shuttleSpeed:0.8,eventStep:'idle'}},
 {title:"Step through the shared events",
  narration:"Step the pulse through emission, reflection, and reception: the same event markers light up in the cabin snapshots and in the triangle of panel (c). Both observers agree on the sequence of events — only the geometry between them differs.",
  state:{observerFrame:'earth',eventStep:'reception'}}
];
var stepI=0;
function applyStep(i){
  stepI=Math.max(0,Math.min(demoSteps.length-1,i));
  var s=demoSteps[stepI];
  if(s.state.observerFrame) toggle_observerFrame(s.state.observerFrame);
  if(s.state.shuttleSpeed!=null){
    v=s.state.shuttleSpeed;
    document.getElementById('shuttleSpeedInput').value=v;
    document.getElementById('shuttleSpeedVal').value=v.toFixed(2);
  }
  setEvent(s.state.eventStep||'idle');
  document.getElementById('demoNarration').textContent=(stepI+1)+'. '+s.title+' — '+s.narration;
  document.getElementById('stepLabel').textContent=' '+(stepI+1)+' / '+demoSteps.length+' ';
}
function nextStep(){ applyStep(stepI+1); }
function prevStep(){ applyStep(stepI-1); }

/* hover explanations on key marks */
draw.rect(230,270).move(35,45).fill('transparent').css('cursor','pointer')
  .on('mousemove',function(e){showTooltip("Astronaut frame: pulse path is vertical, length 2D, time Δτ",e);})
  .on('mouseleave',hideTooltip)
  .on('click',function(){showPopup('Panel (a)',"In the shuttle the light clock is at rest, so the pulse goes straight up and back: path 2D, elapsed proper time Δτ = 2D/c.");});

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

