function clock(g,cx,cy,r,frac,label,labColor){
  var c=g.group();
  c.circle(2*r).center(cx,cy).fill('#fff').stroke({color:'#555',width:2});
  for(var i=0;i<12;i++){var a=i*Math.PI/6;
    c.line(cx+(r-3)*Math.cos(a),cy+(r-3)*Math.sin(a),cx+r*Math.cos(a),cy+r*Math.sin(a)).stroke({color:'#888',width:1});}
  var fa=-Math.PI/2+frac*2*Math.PI;
  c.polygon([[cx,cy],[cx+r*0.8*Math.cos(fa),cy+r*0.8*Math.sin(fa)],[cx+r*0.8*Math.cos(fa+0.5),cy+r*0.8*Math.sin(fa+0.5)]]
    .map(function(p){return p[0]+','+p[1];}).join(' ')).fill(TEAL).opacity(0.7);
  c.line(cx,cy,cx,cy-r*0.7).stroke({color:'#333',width:2});
  if(label) T(c,label,cx+r+8,cy-7,15,labColor||'#222','start','bold');
