  b.circle(9).center(cx,cy).fill(YELLOW).stroke({color:'#c90',width:1});
  return b;
}
function arrowHead(g,x,y,ang,color){
  var s=7, p=[[0,0],[-s,-s*0.5],[-s,s*0.5]];
