  document.getElementById('stepLabel').textContent=' '+(stepI+1)+' / '+demoSteps.length+' ';
}
function nextStep(){ applyStep(stepI+1); }
function prevStep(){ applyStep(stepI-1); }

applyStep(0);
window.__markRendered();
