  cab.line(263,120,273,120).stroke({color:'#444',width:1.5});
  cab.line(263,351,273,351).stroke({color:'#444',width:1.5});
  T(cab,'D',282,228,15);
  /* event highlight */
  if(evIdx===1) cab.circle(16).center(170,343).fill('none').stroke({color:'#e33',width:3});
  if(evIdx===2) cab.circle(14).center(190,124).fill('none').stroke({color:'#e33',width:3});
  if(evIdx===3) cab.circle(16).center(191,343).fill('none').stroke({color:'#e33',width:3});
